svg.script:
// 
  const pathElement = document.getElementById('star3d-path');
  const cx = 340, cy = 280; 
  const size = 126; // Tăng từ 95 lên 126 để áp sát vòng tròn r=132 (cách ~1.6 mm)

  // Tọa độ gốc 3D cố định
  const baseVertices = [
    {x: 0, y: -size, z: 0},
    {x: size * 0.942, y: size * 0.333, z: 0},
    {x: -size * 0.471, y: size * 0.333, z: size * 0.816},
    {x: -size * 0.471, y: size * 0.333, z: -size * 0.816},

    {x: 0, y: size, z: 0},
    {x: -size * 0.942, y: -size * 0.333, z: 0},
    {x: size * 0.471, y: -size * 0.333, z: -size * 0.816},
    {x: size * 0.471, y: -size * 0.333, z: size * 0.816}
  ];

  const edgePairs = [
    [0,1], [0,2], [0,3], [1,2], [2,3], [3,1], // Khối 1
    [4,5], [4,6], [4,7], [5,6], [6,7], [7,5]  // Khối 2
  ];

  // Thiết lập các góc xoay
  let theta = 0;                  // Gia tốc góc xoay tự thân
  const speed = 0.012;            // Tốc độ xoay tự thân
  const tiltX = 15 * Math.PI / 180; // Nghiêng 15 độ về phía trước tạo chiều sâu
  const tiltZ = 5 * Math.PI / 180;  // Độ lệch trục 5 độ ban đầu

  function rotate3D() {
    theta -= speed; // Lõi tự xoay theo chiều kim đồng hồ (CW)

    const cosT = Math.cos(theta), sinT = Math.sin(theta);
    const cosX = Math.cos(tiltX), sinX = Math.sin(tiltX);
    const cosZ = Math.cos(tiltZ), sinZ = Math.sin(tiltZ);

    const projected = baseVertices.map(v => {
      // 1. Tự xoay quanh trục dọc cục bộ (Y)
      const x1 = v.x * cosT - v.z * sinT;
      const z1 = v.x * sinT + v.z * cosT;
      const y1 = v.y;

      // 2. Nghiêng Pitch (X) tạo chiều sâu 3D
      const x2 = x1;
      const y2 = y1 * cosX - z1 * sinX;
      const z2 = y1 * sinX + z1 * cosX;

      // 3. Nghiêng Roll (Z) lệch trục 5 độ
      const x3 = x2 * cosZ - y2 * sinZ;
      const y3 = x2 * sinZ + y2 * cosZ;

      return { x: x3, y: y3 };
    });

    let pathData = "";
    edgePairs.forEach(edge => {
      const p1 = projected[edge[0]];
      const p2 = projected[edge[1]];

      const screenX1 = cx + p1.x;
      const screenY1 = cy + p1.y;
      const screenX2 = cx + p2.x;
      const screenY2 = cy + p2.y;

      pathData += `M ${screenX1} ${screenY1} L ${screenX2} ${screenY2} `;
    });

    pathElement.setAttribute('d', pathData);
    requestAnimationFrame(rotate3D);
  }

  rotate3D();
//
